// Street-name plates & door numbers of the detailed city (gap #12), generated by tools/build-plates.py from the
// Ajuntament de València's *Portals* (every street door and its number) and *Eixos lineals dels carrers* (street names),
// CC BY 4.0, with OpenStreetMap's particles (ODbL). No dependency on three.js, so the tests decode it too.
//
// VPL1 (gzipped): 'VPL1', u32 header length, JSON header { plates, doors, names: [[type, particle, name, subtitle]],
//   suffixes, buildings: { buildings, boxes, fnv }, plateY, plateEdge, doorY, doorYOld, source }, then zigzag varint
//   columns: plates [ref (delta), end, name], doors [ref (delta), t (0.1 m along the wall), number, suffix].
//   ref = box index * 4 + side of a real building's wall (vlc-buildings.js), the walls as buildings.js walks them.

export function decodeVarints(bytes, at, n) {
  const out = new Array(n);
  for (let i = 0; i < n; i++) {
    let v = 0, shift = 0, b;
    do {
      b = bytes[at++];
      v += (b & 0x7f) * 2 ** shift;
      shift += 7;
    } while (b & 0x80);
    out[i] = v % 2 ? -(v + 1) / 2 : v / 2;
  }
  return { out, at };
}

// FNV-1a over the buildings' box array: the plates refer to box walls and must be rebuilt with the buildings
export function buildingsHash(boxes) {
  let h = 0x811c9dc5;
  for (let i = 0; i < boxes.length; i++) h = Math.imul(h ^ (boxes[i] & 0xffff), 0x01000193) >>> 0;
  return h;
}

// a box wall in world metres: a & b ends (b - a runs along the wall, the street on its +n side), unit t, outward n
function wallGeometry(R, boxBuilding, ref) {
  const k = ref >> 2, side = ref & 3;
  const i = boxBuilding[k];
  const px = R.frames[i * 3], pz = R.frames[i * 3 + 1], th = R.frames[i * 3 + 2];
  const cs = Math.cos(th), sn = Math.sin(th);
  const x0 = R.boxes[k * 5] / 10, x1 = R.boxes[k * 5 + 1] / 10, z0 = R.boxes[k * 5 + 2] / 10, z1 = R.boxes[k * 5 + 3] / 10;
  const [ax, az, bx, bz, nx, nz] = side === 0 ? [x0, z1, x0, z0, -1, 0] : side === 1 ? [x1, z0, x1, z1, 1, 0]
    : side === 2 ? [x0, z0, x1, z0, 0, -1] : [x1, z1, x0, z1, 0, 1];
  // buildings.js toWorld (x, z relative to the frame origin)
  const wx = (x, z) => px + x * cs + z * sn, wz = (x, z) => pz - x * sn + z * cs;
  const len = side < 2 ? z1 - z0 : x1 - x0;
  const a = [wx(ax, az), wz(ax, az)], b = [wx(bx, bz), wz(bx, bz)];
  return { a, b, len, tx: (b[0] - a[0]) / len, tz: (b[1] - a[1]) / len, nx: nx * cs + nz * sn, nz: -nx * sn + nz * cs, building: i };
}

/**
 * `bytes`: the inflated vlc-plates file; `R`: REAL_BUILDINGS (vlc-buildings.js). Returns { head, plates, doors, stale }:
 * plates { x, z (anchor, PLATE_EDGE in from the corner), sx, sz (along the wall, away from the corner), nx, nz (facing),
 * room (wall left for the plate), y, name: [type, particle, name, subtitle] }, doors { x, z, nx, nz, y, text, style
 * (0 navy enamel, 1 white tile) }. `stale` if the buildings changed since the plates were built (then none are given).
 */
export function decodePlates(bytes, R) {
  const view = new DataView(bytes.buffer, bytes.byteOffset, bytes.byteLength);
  const magic = String.fromCharCode(...bytes.subarray(0, 4));
  if (magic !== 'VPL1') throw new Error('Invalid plate data.');
  const hl = view.getUint32(4, true);
  const head = JSON.parse(new TextDecoder().decode(bytes.subarray(8, 8 + hl)));
  const B = head.buildings;
  if (!R || R.count !== B.buildings || R.boxCount !== B.boxes || buildingsHash(R.boxes) !== B.fnv) {
    return { head, plates: [], doors: [], stale: true };
  }
  let at = 8 + hl;
  const col = (n) => { const r = decodeVarints(bytes, at, n); at = r.at; return r.out; };
  const undelta = (c) => { for (let i = 1; i < c.length; i++) c[i] += c[i - 1]; return c; };
  const pRef = undelta(col(head.plates)), pEnd = col(head.plates), pName = col(head.plates);
  const dRef = undelta(col(head.doors)), dT = col(head.doors), dNum = col(head.doors), dSfx = col(head.doors);

  const boxBuilding = new Uint32Array(R.boxCount);
  for (let i = 0, k = 0; i < R.count; i++) for (let j = 0; j < R.counts[i]; j++) boxBuilding[k++] = i;
  const yearOf = (i) => (R.meta[i * 4 + 2] ? (R.meta[i * 4 + 2] + 150) * 10 : 0);

  const plates = new Array(head.plates);
  for (let i = 0; i < head.plates; i++) {
    const w = wallGeometry(R, boxBuilding, pRef[i]);
    const [cx, cz] = pEnd[i] ? w.b : w.a;
    const sx = pEnd[i] ? -w.tx : w.tx, sz = pEnd[i] ? -w.tz : w.tz;
    plates[i] = {
      x: cx + sx * head.plateEdge, z: cz + sz * head.plateEdge, sx, sz, nx: w.nx, nz: w.nz,
      room: Math.min(2.5, w.len - head.plateEdge), y: head.plateY, name: head.names[pName[i]], building: w.building
    };
  }
  const doors = new Array(head.doors);
  for (let i = 0; i < head.doors; i++) {
    const w = wallGeometry(R, boxBuilding, dRef[i]);
    const t = Math.min(Math.max(dT[i] / 10, 0), w.len);
    const year = yearOf(w.building);
    // style by building: the white tile with blue numerals is commoner on the old houses (reference photos)
    const h = Math.imul(w.building, 2654435761) >>> 0;
    const style = h % 100 < (year > 0 && year < 1940 ? 40 : 12) ? 1 : 0;
    const sfx = head.suffixes[dSfx[i]];
    doors[i] = {
      x: w.a[0] + w.tx * t, z: w.a[1] + w.tz * t, nx: w.nx, nz: w.nz, tx: w.tx, tz: w.tz,
      y: year > 0 && year < 1920 ? head.doorYOld : head.doorY,
      text: String(dNum[i]), suffix: sfx, style, building: w.building
    };
  }
  return { head, plates, doors, stale: false };
}

// the browser loader: fetch & inflate (as vlc-buildings.js does)
export async function loadPlates(R) {
  const response = await fetch(new URL('./vlc-plates.bin.gz', import.meta.url));
  if (!response.ok) throw new Error(`Plate data request failed: ${response.status}`);
  const body = new Uint8Array(await response.arrayBuffer());
  const data = body[0] === 0x1f && body[1] === 0x8b
    ? new Uint8Array(await new Response(new Response(body).body.pipeThrough(new DecompressionStream('gzip'))).arrayBuffer())
    : body;
  return decodePlates(data, R);
}
